mapper.select:
/*****************deleteProperty 실행!!!******************/
delete from dental_materials where id=#{id}::int4
RETURNING name

mapper.insert:
/*****************insertProperty 실행!!!******************/
INSERT INTO dental_materials (category, code, name, diameter, height, quantity,gheight,cuff,icode)
VALUES (
            #{category}
           ,#{code}
           ,#{name}
           ,#{diameter}::numeric(5,2)
           ,#{height}::numeric(5,2)
           ,#{quantity}::int4
           ,#{gheight}::numeric(5,2)
           ,#{cuff}::int4
            ,#{icode}
       );
